def runSim(bash, mesh_name, object_name, object_depth, basic_name):
    # Command to run simulation with GUI
    #cmd = f'{bash} -a grasping_3.py --argv {mesh_name} --argv {object_name} --argv {object_depth} --argv {basic_name}'

    # Command to run simulation without GUI 
    cmd = f'{bash} -g batch -n 40 grasping_3.py --argv {mesh_name} --argv {object_name} --argv {object_depth} --argv {basic_name}'
    
    output = subprocess.run(cmd, shell=True, text=True, capture_output=True)
    # print(cmd)
    return output


def get_fem_output():
    """
    Simulate a FEM simulation and generate a csv file with data output
    return: gantry_data - data list of the following:
    """
    os.chdir(os.getcwd() + '/../FEM')
    minMeshSize = 0.5
    maxMeshSize = 1.2
    mass = 0.014697

    gantry_data = []

    pool = multiprocessing.Pool()
    results = []
    # Running sim
    result = pool.apply_async(runSim(bash, mesh_name, object_name))
    results.append(result)

    for result in results:
        try:
            simOutput = result.get()
            
            print(f"Extracting Data for {maxMeshSize} Mesh Size", flush=True)
            data = [minMeshSize, maxMeshSize]
            data.extend(extractData(simOutput, 'fem'))
            gantry_data.append(data)

        except multiprocessing.TimeoutError:
            continue

    pool.close()

    header = ['Minimum Mesh Size', 'Maximum Mesh Size', 'Nodes', 'Elements', 'Norm of Contact Force', 'Tip Displacement', 'Maximum Von Mises', 'Runtime']
    createCSV("get_fem_output", header, gantry_data)
    return gantry_data


def extractData(output, mode):
    data = []
    contactForce = 0
    avgDisplacement = 0
    highestDisplacement = 0
    runtime = 0
    vonMises = 0
    tipDisplacement = 0
    for line in output.splitlines():
        if "Info    : Writing 'Data/" in line:
            data.extend(([int(s) for s in prevLine.split() if s.isdigit()]))
        elif "LNorm of the contact force: " in line:
            contactForce = re.findall("\d+\.\d+", line)[0]
            # contactForce = round(contactForce_raw, 3)
        # elif "Average Displacement" in line:
        #     avgDisplacement = re.findall("\d+\.\d+", line)[0]
        # elif "Highest Displacement" in line:
        #     highestDisplacement = re.findall("\d+\.\d+", line)[0]
        # elif "iterations done in" in line:
        #     runtime = re.findall("\d+\.\d+", line)[0]
        elif "LDisplacement at the tip" in line:
            if "nan" not in line:
                tipDisplacement = re.findall("\d+\.\d+", line)[0]

        elif "LMaximum Von Mises Stress is" in line:
            vonMises = re.findall("\d+\.\d+", line)[0]

        prevLine = line

    if mode == 'fem':
        data.extend([contactForce, tipDisplacement, vonMises, runtime])
    else:
        data.extend([contactForce, tipDisplacement, runtime])
    return data 

def createCSV(mode, header, gantry_data):
    currentTime = datetime.datetime.now()
    formattedTime = currentTime.strftime("%H-%M-%S")

    with open(f'output-{mode}-{formattedTime}.csv', 'w', encoding='UTF8', newline='') as f:
        writer = csv.writer(f)

        # write the header
        writer.writerow(header)

        # write multiple rows
        writer.writerows(gantry_data)


